    ?><form method="get" class="ink-sheet ink-filter-form"><input type="hidden" name="tab" value="history"><?php if(!empty($_GET['container_id_filter'])):?><input type="hidden" name="container_id_filter" value="<?=(int)$_GET['container_id_filter']?>"><?php endif;?><div class="ink-filter-fields"><label class="ink-field ink-filter-query"><span>Cor, fórmula, lote, recipiente, colaborador, cliente ou artigo</span><input class="form-control" name="q" value="<?=h($_GET['q']??'')?>" placeholder="Pesquisar no histórico…"></label><label class="ink-field"><span>ID da OF</span><input class="form-control" type="number" min="1" name="order_id" value="<?=h($_GET['order_id']??'')?>"></label><label class="ink-field"><span>Desde</span><input class="form-control" type="date" name="from" value="<?=h($_GET['from']??'')?>"></label><label class="ink-field"><span>Até</span><input class="form-control" type="date" name="to" value="<?=h($_GET['to']??'')?>"></label></div><div class="ink-toolbar"><button class="btn btn-primary" type="submit">Filtrar histórico</button><?php ink_link(['tab'=>'history'],'Limpar filtros','ink-text-link');?></div></form><?php
    $sql='SELECT e.*,u.name operator,b.code container_code,b.lot,m.code mix_code FROM erp_ink_events e JOIN users u ON u.id=e.user_id LEFT JOIN erp_ink_containers b ON b.id=e.container_id LEFT JOIN erp_ink_mixes m ON m.id=COALESCE(b.mix_id,CASE WHEN e.entity="mix" THEN e.entity_id END) LEFT JOIN erp_ink_formulas f ON f.id=COALESCE(m.formula_id,CASE WHEN e.entity="formula" THEN e.entity_id END) LEFT JOIN erp_colors c ON c.id=COALESCE(f.color_id,CASE WHEN e.entity="color" THEN e.entity_id END) LEFT JOIN erp_ink_color_details cd ON cd.color_id=c.id LEFT JOIN erp_customers cu ON cu.id=cd.customer_id LEFT JOIN erp_finished_products ar ON ar.id=cd.article_id WHERE 1=1';$args=[];
    if(!empty($_GET['q'])){$sql.=' AND COALESCE(b.code,"")||" "||COALESCE(b.lot,"")||" "||COALESCE(m.code,"")||" "||COALESCE(f.family,"")||" "||COALESCE(c.code,"")||" "||COALESCE(c.name,"")||" "||COALESCE(c.pantone,"")||" "||u.name||" "||COALESCE(cu.name,"")||" "||COALESCE(ar.code,"") LIKE ?';$args[]='%'.$_GET['q'].'%';}
    foreach(['order_id'=>'e.production_order_id','container_id_filter'=>'e.container_id'] as $key=>$col)if(!empty($_GET[$key])){$sql.=' AND '.$col.'=?';$args[]=(int)$_GET[$key];}
    if(!empty($_GET['from'])){$sql.=' AND e.created_at>=?';$args[]=$_GET['from'].' 00:00:00';}if(!empty($_GET['to'])){$sql.=' AND e.created_at<=?';$args[]=$_GET['to'].' 23:59:59';}
    $rows=$ink->query($sql.' ORDER BY e.id DESC LIMIT 300',$args);$labels=['cor_guardada'=>'Cor guardada','formula_rascunho'=>'Rascunho de fórmula','formula_estado'=>'Estado da fórmula','preparacao'=>'Preparação','entrada'=>'Entrada de recipiente','result'=>'Avaliação','correct'=>'Correção','consume'=>'Consumo','return'=>'Devolução','loss'=>'Perda','adjust'=>'Acerto','container_state'=>'Estado do recipiente','print'=>'Impressão','anexo'=>'Referência anexada'];
    if(!$rows)ink_empty('Sem movimentos para estes filtros','Experimente outro período ou uma pesquisa mais abrangente.','bi-clock-history');else foreach($rows as $e){
        $payload=json_decode($e['payload_json'],true);?><details class="ink-event"><summary><span class="ink-event-icon"><i class="bi bi-clock-history" aria-hidden="true"></i></span><span><strong><?=h($labels[$e['action']]??$e['action'])?></strong><small><?=h($e['operator'].' · '.$e['created_at'])?></small></span><span class="ink-event-reference"><?=h($e['container_code']?:($e['mix_code']?:'Biblioteca'))?></span><span class="ink-number"><?=$e['delta_mg']?h(($e['delta_mg']>0?'+':'').ink_mass($e['delta_mg'])):'—'?></span><i class="bi bi-chevron-down" aria-hidden="true"></i></summary><div class="ink-event-detail"><dl class="ink-facts"><div><dt>Ordem de Fabrico</dt><dd><?=h($e['production_order_id']?:'—')?></dd></div><div><dt>Lote</dt><dd><?=h($e['lot']?:'—')?></dd></div><div><dt>Observações</dt><dd><?=h($payload['notes']??'—')?></dd></div></dl><?php if(!empty($payload['composition']))ink_composition($payload['composition']);elseif(!empty($payload['actual']))ink_composition($payload['actual']);?><details class="ink-technical"><summary>Registo técnico completo</summary><pre><?=h(json_encode($payload,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre></details></div></details><?php
    }
}else{
    $q=trim($_GET['q']??'');$selectedColor=(int)($_GET['color_id']??0);
    if($selectedColor){
        $rows=$ink->query('SELECT c.*,d.hex,d.substrate,d.notes FROM erp_colors c LEFT JOIN erp_ink_color_details d ON d.color_id=c.id WHERE c.id=?',[$selectedColor]);if(!$rows)throw new RuntimeException('Cor não encontrada.');$c=$rows[0];
        echo '<div class="ink-breadcrumb">';ink_link(['tab'=>'search','q'=>$q],'Cores','ink-text-link','bi-arrow-left');echo '</div><div class="ink-color-heading">';ink_swatch($c['hex'],true);ink_heading($c['code'].' — '.$c['name'],($c['pantone']?'Pantone '.$c['pantone'].' · ':'').($c['substrate']?:'Referência TISSER'));echo '</div>';
        $formulas=$ink->query('SELECT * FROM erp_ink_formulas WHERE color_id=? AND status="Aprovada" ORDER BY version DESC',[$selectedColor]);
        if(!$formulas)ink_empty('Esta cor ainda não tem fórmulas aprovadas','A biblioteca fica disponível para preparação após validação.','bi-droplet');
        foreach($formulas as $f){echo '<article class="ink-sheet">';ink_heading($f['family'].' · Versão '.$f['version'],$f['substrate']);ink_composition(json_decode($f['components_json'],true));if($f['notes'])echo '<p class="ink-note mt-3">'.h($f['notes']).'</p>';
            $attachments=$ink->query('SELECT id,name FROM erp_ink_formula_attachments WHERE formula_id=?',[$f['id']]);foreach($attachments as $a)echo '<a class="ink-file" href="ink_formula_attachment.php?id='.$a['id'].'"><i class="bi bi-paperclip" aria-hidden="true"></i> '.h($a['name']).'</a>';
            echo '<div class="ink-toolbar">';ink_link(['tab'=>'prepare','formula_id'=>$f['id']],'Preparar esta fórmula','btn btn-primary','bi-droplet');echo '</div></article>';
        }
        if($canCreate)ink_link(['tab'=>'library','editor'=>'color','color_id'=>$selectedColor],'Editar cor','btn btn-outline-secondary','bi-pencil');
    }else{
        ?><div class="ink-page-heading"><div><h2>Encontrar uma cor</h2><p>Pesquise a referência e consulte as fórmulas aprovadas.</p></div><?php if($canCreate)ink_link(['tab'=>'library','editor'=>'color'],'Nova cor','btn btn-outline-primary','bi-plus-lg');?></div><form method="get" class="ink-searchbar"><input type="hidden" name="tab" value="search"><label class="ink-search-field"><i class="bi bi-search" aria-hidden="true"></i><input autofocus class="form-control" name="q" value="<?=h($q)?>" placeholder="Código TISSER, Pantone, cliente, artigo ou nome…" aria-label="Pesquisar cor"></label><button class="btn btn-primary" type="submit">Pesquisar</button></form><?php
        $rows=$ink->query('SELECT c.*,d.hex,d.status,d.substrate,cu.name customer,ar.code article,(SELECT COUNT(*) FROM erp_ink_formulas f WHERE f.color_id=c.id AND f.status="Aprovada") formula_count FROM erp_colors c LEFT JOIN erp_ink_color_details d ON d.color_id=c.id LEFT JOIN erp_customers cu ON cu.id=d.customer_id LEFT JOIN erp_finished_products ar ON ar.id=d.article_id WHERE c.code||" "||c.name||" "||COALESCE(c.pantone,"")||" "||COALESCE(cu.name,"")||" "||COALESCE(ar.code,"") LIKE ? ORDER BY c.code LIMIT 200',['%'.$q.'%']);
        if(!$rows)ink_empty('Nenhuma cor encontrada','Tente outra referência, nome ou código Pantone.');else{
            echo '<div class="ink-list-caption">'.count($rows).' cor(es) encontradas</div><div class="ink-color-grid">';foreach($rows as $c){echo '<a class="ink-color-card" href="'.h(ink_url(['tab'=>'search','color_id'=>$c['id'],'q'=>$q])).'">';ink_swatch($c['hex'],true);echo '<div class="ink-color-card-info"><span class="ink-eyebrow">'.h($c['code']).'</span><h3>'.h($c['name']).'</h3><p>'.h($c['pantone']?'Pantone '.$c['pantone']:($c['substrate']?:'Referência TISSER')).'</p><span class="ink-formula-count">'.(int)$c['formula_count'].' fórmula(s) aprovadas</span></div><i class="bi bi-arrow-right" aria-hidden="true"></i></a>';}echo '</div>';
        }
        if(!empty($inkUser['is_admin'])){$r=$ink->query('SELECT (SELECT COUNT(*) FROM erp_ink_formulas WHERE status="Aprovada") formulas,(SELECT COUNT(*) FROM erp_ink_mixes WHERE created_at>=date("now","start of month")) mixes,(SELECT COALESCE(SUM(available_mg),0) FROM erp_ink_containers) stock')[0];?><div class="ink-metrics ink-metrics-bottom"><div><span>Fórmulas aprovadas</span><strong><?=(int)$r['formulas']?></strong></div><div><span>Preparações este mês</span><strong><?=(int)$r['mixes']?></strong></div><div><span>Stock físico</span><strong><?=h(ink_mass($r['stock']))?></strong></div></div><?php }
    }
}
?>
</div></section>
